### Option 1: HashiCorp Vault

```javascript
const nodeVault = require('node-vault');

const vault = async () => {
  const vaultClient = nodeVault({
    endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
    token: process.env.VAULT_TOKEN // Only this token is in .env
  });

  try {
    const result = await vaultClient.read('secret/data/app');
    return result.data.data;
  } catch (error) {
    console.error('Failed to fetch secrets from Vault');
    throw error;
  }
};

// Usage
