## Improved Architecture Pattern

```javascript
// secrets-manager.js
class SecretsManager {
  constructor() {
    this.cache = {};
    this.cacheExpiry = {};
    this.CACHE_TTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(key, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.cache[key] && this.cacheExpiry[key] > Date.now()) {
      return this.cache[key];
    }

    // Fetch from secrets manager
    const secret = await this.fetchFromVault(key);

    // Cache the result
    this.cache[key] = secret;
    this.cacheExpiry[key] = Date.now() + this.CACHE_TTL;

    return secret;
  }

  async fetchFromVault(key) {
    // Implementation varies by provider
    // Example for environment-based (development only)
    if (process.env.NODE_ENV === 'development') {
      if (!process.env[key]) {
        throw new Error(`Missing secret: ${key}`);
      }
      return process.env[key];
    }

    // Production: Fetch from actual secrets manager
