```javascript
const AWS = require('aws-sdk');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (!forceRefresh && cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secret = response.SecretString 
        ? JSON.parse(response.SecretString) 
        : null;

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      throw error;
    }
  }

  async getJwtSecret() {
    const secret = await this.getSecret('prod/app/jwt');
    return secret.JWT_SECRET;
  }

  async getDatabaseCredentials() {
    const secret = await this.getSecret('prod/app/database');
    return {
      host: secret.DB_HOST,
      username: secret.DB_USERNAME,
      password: secret.DB_PASSWORD,
      database: secret.DB_NAME
    };
  }

  clearCache() {
    this.cache.clear();
  }
}

// Export singleton instance
module.exports = new SecretsManager();
```

