/**
 * Secrets Manager Module
 * Handles secure secret retrieval with caching and fallback support
 *
 * Supports multiple providers:
 * - AWS Secrets Manager (Production)
 * - Environment Variables (Development/Local)
 * - File-based .env (Fallback - not recommended for production)
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Configuration
const CONFIG = {
  cacheEnabled: process.env.SECRETS_CACHE_ENABLED !== 'false',
  cacheTTL: parseInt(process.env.SECRETS_CACHE_TTL) || 5 * 60 * 1000, // 5 minutes
  provider: process.env.SECRETS_PROVIDER || 'auto', // 'aws', 'env', or 'auto'
  awsRegion: process.env.AWS_REGION || 'us-east-1',
};

// Cache storage
let secretsCache = null;
let cacheExpiry = null;

// AWS Secrets Manager client
let smClient = null;

function getSecretsManagerClient() {
  if (!smClient) {
    smClient = new SecretsManagerClient({
      region: CONFIG.awsRegion,
      // Credentials will be loaded automatically from:
      // - Environment variables (AWS_ACCESS_KEY_ID, etc.)
      // - IAM role (EC2/ECS/Lambda)
      // - ~/.aws/credentials
      // - ECS task roles
    });
  }
  return smClient;
}

/**
 * Detect which secrets provider to use
 */
function detectProvider() {
  if (CONFIG.provider !== 'auto') {
    return CONFIG.provider;
  }

  // Check if AWS credentials are available
  if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY) {
    return 'aws';
  }

  // Check if running on AWS infrastructure
  if (process.env.AWS_EXECUTION_ENV || process.env.AWS_REGION) {
    return 'aws';
  }

  // Default to environment variables for local development
  return 'env';
}

/**
 * Get secret from AWS Secrets Manager
 */
async function getFromAWS(secretName) {
  try {
    const client = getSecretsManagerClient();

    const response = await client.send(
      new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT', // Get current version
      })
    );

    if (response.SecretString) {
      // Try to parse as JSON, otherwise return as string
      try {
        const parsed = JSON.parse(response.SecretString);
        return { source: 'aws', data: parsed, versionId: response.VersionId };
      } catch {
        return { source: 'aws', data: { value: response.SecretString }, versionId: response.VersionId };
      }
    }

    throw new Error('SecretString is empty');
  } catch (error) {
    console.error(`Error fetching secret from AWS: ${secretName}`, {
      code: error.name,
      message: error.message,
    });
    throw error;
  }
}

/**
 * Get secret from environment variables
 */
function getFromEnv(secretName) {
  // Map secret names to environment variable names
  const envMappings = {
    'prod/jwt/secret': 'JWT_SECRET',
    'prod/database/url': 'DATABASE_URL',
    'prod/anthropic/key': 'ANTHROPIC_API_KEY',
    'prod/stripe/key': 'STRIPE_SECRET_KEY',
    'prod/aws/access-key-id': 'AWS_ACCESS_KEY_ID',
    'prod/aws/secret-access-key': 'AWS_SECRET_ACCESS_KEY',
  };

  const envVarName = envMappings[secretName] || secretName.toUpperCase().replace(/-/g, '_');
  const value = process.env[envVarName];

  if (!value) {
    throw new Error(`Environment variable ${envVarName} not found`);
  }

  return { source: 'env', data: { value }, versionId: 'env' };
}

/**
 * Get secret from fallback mechanism (.env file via dotenv)
 * Use only for development/testing
