```javascript
const AWS = require('aws-sdk');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Initialize Secrets Manager client
const secretsClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

/**
 * Fetch a secret from AWS Secrets Manager
 */
async function getSecret(secretName) {
  try {
    const response = await secretsClient.send(
      new GetSecretValueCommand({ SecretId: secretName })
    );

    return response.SecretString 
      ? JSON.parse(response.SecretString) 
      : response.SecretBinary;
  } catch (error) {
    console.error(`Error fetching secret ${secretName}:`, error);
    throw error;
  }
}

// Initialize app with secrets
async function initializeApp() {
  try {
    // Fetch all secrets from AWS Secrets Manager
    const dbSecrets = await getSecret('prod/database/credentials');
    const awsSecrets = await getSecret('prod/aws/credentials');
    const apiKeys = await getSecret('prod/api/keys');

    // Configure application
    process.env.DATABASE_URL = `postgres://${dbSecrets.username}:${dbSecrets.password}@${dbSecrets.host}:5432/${dbSecrets.dbname}`;
    process.env.AWS_ACCESS_KEY_ID = awsSecrets.accessKeyId;
    process.env.AWS_SECRET_ACCESS_KEY = awsSecrets.secretAccessKey;
