const { SSMClient, GetParametersByPathCommand } = require('@aws-sdk/client-ssm');

const ssmClient = new SSMClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

/**
 * Fetch all parameters from a path in AWS Parameter Store
 */
async function getParametersByPath(path, withDecryption = true) {
  try {
    const response = await ssmClient.send(
      new GetParametersByPathCommand({
        Path: path,
        Recursive: true,
        WithDecryption: withDecryption
      })
    );

    // Convert to object
    const params = {};
    response.Parameters.forEach(param => {
      const name = param.Name.split('/').pop();
      params[name] = param.Value;
    });

    return params;
  } catch (error) {
    console.error(`Error fetching parameters from ${path}:`, error);
    throw error;
  }
}

async function initializeApp() {
  try {
    // Fetch all parameters
    const dbParams = await getParametersByPath('/prod/database/');
    const awsParams = await getParametersByPath('/prod/aws/');
    const apiParams = await getParametersByPath('/prod/api/');

