### **4. Secrets Rotation Strategy**

```javascript
// config/secrets-rotation.js

/**
 * Graceful secret rotation handler
 */
class SecretsRotator {
  constructor() {
    this.secretCache = new Map();
    this.ttl = 5 * 60 * 1000; // 5 minutes

    // Start refresh interval
    setInterval(() => this.refreshAll(), this.ttl);
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.secretCache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.ttl) {
      return cached.value;
    }

    // Fetch fresh value
    const value = await this.fetchSecret(secretName);
    this.secretCache.set(secretName, {
      value,
      timestamp: Date.now()
    });

    return value;
  }

  async fetchSecret(secretName) {
    // Implementation depends on your secrets manager
    return await getParameterFromAWS(secretName);
  }

  async refreshAll() {
    console.log('🔄 Refreshing secrets...');
    for (const name of this.secretCache.keys()) {
      try {
        await this.getSecret(name);
      } catch (error) {
        console.error(`Failed to refresh ${name}:`, error.message);
      }
    }
  }
}

module.exports = new SecretsRotator();
```

