### 🛡️ Secure Secrets Management Recommendations

#### **Option 1: AWS Secrets Manager (Recommended for AWS deployments)**

```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const { fromNodeProviderChain } = require('@aws-sdk/credential-providers');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
      credentials: fromNodeProviderChain(), // Uses IAM roles, not keys
    });
    this.cache = new Map();
    this.cacheTTL = 300; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    const now = Date.now();
    const cached = this.cache.get(secretName);

    // Return cached value if fresh
    if (!forceRefresh && cached && (now - cached.timestamp) < (this.cacheTTL * 1000)) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secretValue;
      if (response.SecretString) {
        secretValue = response.SecretString;
      } else if (response.SecretBinary) {
        secretValue = Buffer.from(response.SecretBinary).toString('utf-8');
      }

      // Parse JSON if applicable
      try {
        secretValue = JSON.parse(secretValue);
      } catch {
        // Keep as string if not JSON
      }

      // Cache the result
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: now
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }

  // Database connection string
  async getDatabaseUrl() {
    return this.getSecret('prod/database/url');
  }

  // AWS credentials should NOT be stored in Secrets Manager
  // Use IAM roles instead (endpoint on EC2, ECS, EKS, Lambda)
}

// Usage
const secrets = new SecretsManager();
let secretsLoaded = false;

async function loadSecrets() {
  if (secretsLoaded) return;

  const dbUrl = await secrets.getDatabaseUrl();

  // Set process.env for compatibility with existing code
  process.env.DATABASE_URL = dbUrl;

  secretsLoaded = true;
  console.log('Secrets loaded successfully');
}

// Initialize secrets at startup
loadSecrets().catch(console.error);

module.exports = { secrets };
```

