const nodeVault = require('node-vault')();

class VaultSecretsManager {
  constructor() {
    this.vault = nodeVault({
      endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
      token: process.env.VAULT_TOKEN, // Only this token goes to env (short-lived from IAM auth)
    });
    this.cache = new Map();
  }

  async getSecret(path, key = null) {
    try {
      const result = await this.vault.read(`secret/data/${path}`);
      const data = result.data.data;

      return key ? data[key] : data;
    } catch (error) {
      console.error(`Vault error for ${path}:`, error.message);
      throw error;
    }
  }

  async getDatabaseUrl() {
    return this.getSecret('prod/database', 'connection_url');
  }

  async getApiKey(service) {
    return this.getSecret(`prod/api/${service}`, 'key');
  }
}

// Usage with Vault transit encryption
const vault = nodeVault();

// When storing sensitive data:
async function encryptSecret(plaintext) {
  const result = await vault.write('transit/encrypt/my-key', {
    plaintext: Buffer.from(plaintext).toString('base64')
  });
  return result.data.ciphertext;
}

async function decryptSecret(ciphertext) {
  const result = await vault.write('transit/decrypt/my-key', {
    ciphertext
  });
  return Buffer.from(result.data.plaintext, 'base64').toString();
}
