```javascript
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({ region: process.env.AWS_REGION });

async function getSecret(secretName) {
  try {
    const data = await client.getSecretValue({ SecretId: secretName }).promise();
    if (data.SecretString) {
      return JSON.parse(data.SecretString);
    }
    throw new Error('Secret not found');
  } catch (error) {
    console.error('Failed to fetch secret:', error.message);
    if (process.env.NODE_ENV === 'development') {
      // Fallback to .env for local development only
      return process.env;
    }
    throw error;
  }
}

// Application initialization
async function initializeApp() {
  const secrets = await getSecret('myapp/production');
  const JWT_SECRET = secrets.JWT_SECRET;
  const DB_URL = secrets.DATABASE_URL;

  // Start app with secrets
  app.listen(PORT);
}
```

