## ✅ Secure Secrets Management Pattern

### Recommended Architecture

```javascript
// config/secrets.js
class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(name, forceRefresh = false) {
    const cached = this.cache.get(name);

    // Return cached value if fresh
    if (cached && !forceRefresh && Date.now() - cached.timestamp < this.cacheTimeout) {
      return cached.value;
    }

    // Fetch from appropriate source based on environment
    const secret = await this.fetchSecret(name);

    // Cache the secret
    this.cache.set(name, {
      value: secret,
      timestamp: Date.now()
    });

    return secret;
  }

  async fetchSecret(name) {
    const env = process.env.NODE_ENV;

    switch (env) {
      case 'production':
        return this.fetchFromCloudProvider(name);
      case 'staging':
        return this.fetchFromCloudProvider(`staging-${name}`);
      case 'test':
        return process.env[name]; // Use environment variables for tests
      case 'development':
        return process.env[name] || require('dotenv').config().parsed[name];
      default:
        throw new Error(`Unknown environment: ${env}`);
    }
  }

  async fetchFromCloudProvider(name) {
    // AWS Secrets Manager
    const AWS = require('aws-sdk');
    const client = new AWS.SecretsManager();

    try {
      const data = await client.getSecretValue({ SecretId: name }).promise();
      return JSON.parse(data.SecretString);
    } catch (error) {
      console.error(`Failed to fetch secret ${name}:`, error.message);
      throw error;
    }
  }

  // Invalidates cache for a specific secret
  invalidate(name) {
    this.cache.delete(name);
  }

  // Invalidate all secrets (e.g., on secret rotation event)
  invalidateAll() {
    this.cache.clear();
  }
}

module.exports = new SecretsManager();
```

### Application Usage

```javascript
// app.js
const secretsManager = require('./config/secrets');

async function initializeApp() {
  try {
    const secrets = await secretsManager.getSecret('myapp/production');

    // Validate required secrets exist
    const requiredSecrets = ['JWT_SECRET', 'DATABASE_URL', 'API_KEY'];
    const missing = requiredSecrets.filter(key => !secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    // Configure app with secrets
    const app = createApp(secrets);

    app.listen(3000, () => {
      console.log('Server running');
    });

    // Handle secret rotation events
    process.on('SIGUSR2', () => {
      console.log('Rotating secrets...');
      secretsManager.invalidateAll();
    });

  } catch (error) {
    console.error('Failed to initialize:', error);
    process.exit(1);
  }
}

initializeApp();
