          locations: results[match[1]]?.locations || [],
          type: inferSecretType(match[1])
        };
        results[match[1]].locations.push(fullPath);
      }

      const directMatches = content.matchAll(
        /(JWT_SECRET|API_KEY|DATABASE_URL|PASSWORD|TOKEN|PRIVATE_KEY|AWS_[A-Z_]+)/g
