function inferSecretType(name) {
  if (name.includes('JWT')) return 'Authentication Token';
  if (name.includes('PASSWORD')) return 'Password';
  if (name.includes('KEY') && !name.includes('PUBLIC')) return 'API/Secret Key';
  if (name.includes('TOKEN')) return 'Access Token';
  if (name.includes('DATABASE') || name.includes('DB')) return 'Database Credential';
  if (name.includes('AWS')) return 'Cloud Provider Credential';
