## ✅ Recommended: Secrets Manager Integration

Here's a secure implementation using AWS Systems Manager Parameter Store (similar approaches for Azure Key Vault, GCP Secret Manager):

### **Solution 1: AWS Systems Manager Parameter Store**

```javascript
require('dotenv').config(); // Fallback for local development only

const AWS = require('aws-sdk');
const ssm = new AWS.SSM({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Fetch secrets from AWS Parameter Store
 * In production, cache these to avoid redundant API calls
 */
async function getSecret(name, defaultValue = null) {
  // Local development: use environment variables
  if (process.env.NODE_ENV === 'development' || process.env.USE_LOCAL_SECRETS === 'true') {
    return process.env[name] || defaultValue;
  }

  try {
    const params = {
      Name: name,
      WithDecryption: true
    };

    const result = await ssm.getParameter(params).promise();
    return result.Parameter.Value;
  } catch (error) {
    if (error.code === 'ParameterNotFound') {
      return defaultValue;
    }
    console.error(`Failed to fetch secret ${name}:`, error.message);
    throw error;
  }
}

/**
 * Load all required secrets at startup
 */
async function loadSecrets() {
  const secrets = {
    JWT_SECRET: await getSecret('/myapp/jwt/secret'),
    DATABASE_URL: await getSecret('/myapp/database/url'),
    API_KEY_EXTERNAL: await getSecret('/myapp/external/api-key'),
    ENCRYPTION_KEY: await getSecret('/myapp/encryption/key')
  };

  // Validate required secrets
  const requiredSecrets = ['JWT_SECRET'];
  const missing = requiredSecrets.filter(key => !secrets[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }

  return secrets;
}

// Load secrets before starting server
let appSecrets;

async function initializeApp() {
  try {
    appSecrets = await loadSecrets();

    // Initialize Express app with secrets
    const express = require('express');
    const app = express();

    // Make secrets available to the app (carefully!)
    app.set('secrets', appSecrets);

    // ... rest of app setup

    const PORT = await getSecret('/myapp/server/port', '3000');
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
    });

  } catch (error) {
    console.error('Failed to initialize application:', error);
    process.exit(1);
  }
}

initializeApp();

module.exports = app;
```

