/**
 * Production-Ready Secrets Management using AWS Secrets Manager
 * 
 * Benefits:
 * - Secrets encrypted at rest (AES-256)
 * - Automatic rotation support
 * - Fine-grained IAM permissions
 * - Audit logging via CloudTrail
 * - No secrets in code or files
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Initialize client with automatic credential chain
const secretsClient = new SecretsManagerClient({});

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheExpiry = 5 * 60 * 1000; // 5 minutes
  }

  /**
   * Get secret with caching to reduce API calls
   */
  async getSecret(secretName) {
    const cached = this.cache.get(secretName);

    if (cached && Date.now() - cached.timestamp < this.cacheExpiry) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName
      });

      const response = await secretsClient.send(command);

      const secretValue = response.SecretString
        ? JSON.parse(response.SecretString)
        : null;

      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      throw new Error(`Failed to retrieve secret: ${error.message}`);
    }
  }

  /**
   * Load all required application secrets
   */
  async loadApplicationSecrets() {
    const secretNames = {
      // Database secrets
      database: process.env.DATABASE_SECRET_NAME || 'prod/app/database',

      // External API keys
      apiKeys: process.env.API_KEYS_SECRET_NAME || 'prod/app/api-keys',

      // JWT signing key
      jwt: process.env.JWT_SECRET_NAME || 'prod/app/jwt',
    };

    try {
      const [database, apiKeys, jwt] = await Promise.all([
        this.getSecret(secretNames.database),
        this.getSecret(secretNames.apiKeys),
        this.getSecret(secretNames.jwt),
      ]);

      // Set environment variables for application use
      process.env.DATABASE_URL = database.connection_url;
      process.env.DATABASE_USER = database.username;
      process.env.DATABASE_PASSWORD = database.password;

      process.env.AWS_ACCESS_KEY_ID = apiKeys.aws_access_key_id;
      process.env.AWS_SECRET_ACCESS_KEY = apiKeys.aws_secret_access_key;
      process.env.ANTHROPIC_API_KEY = apiKeys.anthropic_api_key;
      process.env.STRIPE_SECRET_KEY = apiKeys.stripe_secret_key;

      process.env.JWT_SECRET = jwt.signing_key;

      return {
        loaded: true,
        count: Object.keys(secretsNames).length
      };
    } catch (error) {
      console.error('Failed to load secrets:', error.message);
      throw error;
    }
  }

  /**
   * Clear cache (useful after secret rotation)
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Get cached secrets info (for monitoring)
   */
  getCacheInfo() {
    return {
      size: this.cache.size,
      entries: Array.from(this.cache.keys())
    };
  }
}

module.exports = new SecretsManager();

