/**
 * Secrets Management using HashiCorp Vault
 * Alternative to AWS Secrets Manager
 */

const axios = require('axios');

class VaultSecretsManager {
  constructor() {
    this.vaultAddress = process.env.VAULT_ADDR || 'http://localhost:8200';
    this.token = process.env.VAULT_TOKEN; // Should be from EC2 IAM/Pod identity
    this.cache = new Map();
    this.client = axios.create({
      baseURL: this.vaultAddress,
      headers: {
        'X-Vault-Token': this.token
      }
    });
  }

  async getSecret(path, key = null) {
    try {
      const response = await this.client.get(`/v1/${path}`);

      const secretData = response.data.data.data || response.data.data;

      if (key) {
        return secretData[key];
      }

      return secretData;
    } catch (error) {
      if (error.response?.status === 403) {
        throw new Error(`Permission denied for secret: ${path}`);
      }
      throw new Error(`Failed to retrieve secret from Vault: ${error.message}`);
    }
  }

  async loadDatabaseSecrets() {
    const secrets = await this.getSecret('secret/data/app/database');

    process.env.DATABASE_URL = `postgresql://${secrets.username}:${secrets.password}@${secrets.host}:${secrets.port}/${secrets.dbname}`;

    return secrets;
  }

  async loadApiKeys() {
    const secrets = await this.getSecret('secret/data/app/api-keys');

    process.env.AWS_ACCESS_KEY_ID = secrets.aws_access_key_id;
    process.env.AWS_SECRET_ACCESS_KEY = secrets.aws_secret_access_key;
    process.env.ANTHROPIC_API_KEY = secrets.anthropic_api_key;
    process.env.STRIPE_SECRET_KEY = secrets.stripe_secret_key;

    return secrets;
  }

  async rotateSecret(path, newData) {
    try {
      await this.client.post(`/v1/${path}`, {
        data: newData
      });
      console.log(`Secret rotated: ${path}`);
    } catch (error) {
      throw new Error(`Failed to rotate secret: ${error.message}`);
    }
  }
}

module.exports = new VaultSecretsManager();

