```javascript
// config.js
require('dotenv').config({ path: `.env.${process.env.NODE_ENV || 'development'}` });

const secretsLoader = {
  // Production: Use AWS Secrets Manager/Vault
  production: async () => {
    const AWS = require('aws-sdk');
    const client = new AWS.SecretsManager({ region: process.env.AWS_REGION });

    // Fetch secrets with caching
    const cache = new Map();

    const getSecret = async (secretId) => {
      if (cache.has(secretId)) {
        return cache.get(secretId);
      }

      const data = await client.getSecretValue({ SecretId: secretId }).promise();
      const secret = data.SecretString;
      cache.set(secretId, secret);

      // TTL-based cache invalidation could be added here
      return secret;
    };

    return {
      databaseUrl: JSON.parse(await getSecret('prod/database')).url,
      awsAccessKeyId: JSON.parse(await getSecret('prod/aws')).accessKeyId,
      awsSecretAccessKey: JSON.parse(await getSecret('prod/aws')).secretAccessKey,
      anthropicApiKey: JSON.parse(await getSecret('prod/apis')).anthropicKey,
      stripeSecretKey: JSON.parse(await getSecret('prod/apis')).stripeKey,
      logfireToken: JSON.parse(await getSecret('prod/apis')).logfireToken,
    };
  },

  // Development/Staging: Use .env files (never in production Git)
  development: () => ({
    databaseUrl: process.env.DATABASE_URL,
    awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
    awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    anthropicApiKey: process.env.ANTHROPIC_API_KEY,
    stripeSecretKey: process.env.STRIPE_SECRET_KEY,
    logfireToken: process.env.LOGFIRE_TOKEN,
  }),

  // Test: Mock secrets or use test fixtures
  test: () => ({
    databaseUrl: 'postgres://test:test@localhost:5432/testdb',
    awsAccessKeyId: 'test-key-id',
    awsSecretAccessKey: 'test-secret-key',
    anthropicApiKey: 'test-ant-key',
    stripeSecretKey: 'REDACTED_STRIPE_TEST',
    logfireToken: 'test-logfire-token',
  }),
};

async function loadConfig() {
  const env = process.env.NODE_ENV || 'development';
  const config = await secretsLoader[env]();

  // Validate
  if (env === 'production') {
    validateRequired(config, [
      'databaseUrl',
      'awsAccessKeyId',
      'awsSecretAccessKey',
      'anthropicApiKey',
    ]);
  }

  return config;
}

function validateRequired(config, required) {
  const missing = required.filter(key => !config[key] || config[key].startsWith('test-') || config[key].includes('mock'));
  if (missing.length > 0) {
    throw new Error(`Invalid or missing production config: ${missing.join(', ')}`);
  }
}

module.exports = { loadConfig };
```

