    'STRIPE_SECRET_KEY'
  ];

  const missing = requiredSecrets.filter(key => !secrets[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }

  // Validate secret format patterns
  const urlPattern = /^postgres:\/\/.+@.+:.+\/.+$/;
  if (!urlPattern.test(secrets.DATABASE_URL)) {
    throw new Error('DATABASE_URL format is invalid');
  }

  return true;
}

async function getSecrets() {
  if (!secretsCache) {
    secretsCache = await loadSecrets();
    validateSecrets(secretsCache);
  }
  return secretsCache;
}

// Clear cache (useful for testing or forced refresh)
function clearSecretCache() {
  secretsCache = null;
}

module.exports = {
  loadSecrets,
  getSecrets,
  validateSecrets,
  clearSecretCache
};
```

