### **Approach 3: Multi-Layer Secrets Strategy** (Enterprise-Ready)

**`config/secretLoader.js`** - Multi-source secret loader:

```javascript
class SecretLoader {
  constructor() {
    this.cache = new Map();
    this.sources = [];
  }

  // Add a secret source (priority order matters)
  addSource(source) {
    this.sources.push(source);
    return this;
  }

  // Get secret value
  async get(key) {
    // Check cache first
    if (this.cache.has(key)) {
      return this.cache.get(key);
    }

    // Try each source in order
    for (const source of this.sources) {
      const value = await source.get(key);
      if (value !== undefined) {
        this.cache.set(key, value);
        // Don't log actual secret values!
        console.log(`✅ Loaded secret: ${key} from ${source.name}`);
        return value;
      }
    }

    throw new Error(`Secret not found: ${key}`);
  }

  // Load multiple secrets at once
  async loadMany(keys) {
    const secrets = {};
    for (const key of keys) {
      secrets[key] = await this.get(key);
    }
    return secrets;
  }

  clearCache() {
    this.cache.clear();
  }
}

// Source: Environment variables
const EnvSource = {
  name: 'Environment Variables',
  get: (key) => process.env[key]
};

// Source: AWS Secrets Manager
const AWSSecretsSource = {
  name: 'AWS Secrets Manager',
  get: async (key) => {
    if (process.env.NODE_ENV !== 'production') return undefined;

    const { SecretsManager } = require('@aws-sdk/client-secrets-manager');
    const client = new SecretsManager({ 
      region: process.env.AWS_REGION || 'us-east-1' 
    });

    try {
      const secretName = process.env.SECRETS_MANAGER_ARN || 
                        `prod/${process.env.APP_NAME}/secrets`;
      const response = await client.getSecretValue({ SecretId: secretName });
      const secrets = JSON.parse(response.SecretString);
      return secrets[key];
    } catch (error) {
      return undefined;
    }
  }
};

// Source: HashiCorp Vault (optional)
const VaultSource = {
  name: 'HashiCorp Vault',
  get: async (key) => {
    if (!process.env.VAULT_ADDR) return undefined;

    const nodeVault = require('node-vault');
    const vault = nodeVault({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN
    });

    try {
      const secretPath = process.env.VAULT_SECRET_PATH || 'secret/data/app';
      const result = await vault.read(secretPath);
      return result.data.data[key];
    } catch (error) {
      return undefined;
    }
  }
};

// Create loader instance with priority order
const secretLoader = new SecretLoader()
  .addSource(EnvSource)                    // Highest priority
  .addSource(AWSSecretsSource)             // Second priority
  .addSource(VaultSource);                 // Lowest priority

module.exports = {
  secretLoader,
  SecretLoader,
  EnvSource,
  AWSSecretsSource,
  VaultSource
};
```

**Usage in `app.js`:**

```javascript
const { secretLoader } = require('./config/secretLoader');

async function bootstrap() {
  // Define required secrets
  const requiredSecrets = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN'
  ];

  try {
    // Load all secrets
    const secrets = await secretLoader.loadMany(requiredSecrets);

    // Validate critical secrets are not empty
    for (const [key, value] of Object.entries(secrets)) {
      if (!value || value.trim() === '') {
        throw new Error(`Secret ${key} is empty or invalid`);
      }

      // Check for default/canary values in production
      if (process.env.NODE_ENV === 'production' && value.includes('CANARY')) {
        console.warn(`⚠️  WARNING: ${key} appears to contain a canary/test value in production!`);
        throw new Error(`Invalid ${key} in production: cannot use test values`);
      }
    }

    // Start application with loaded secrets
    const express = require('express');
    const app = express();

    // Make secrets available to app modules (use injection pattern)
    app.set('secrets', secrets);

    // ... application code

    const PORT = secrets.PORT || process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`✅ Application started successfully`);
      console.log(`🌍 Environment: ${process.env.NODE_ENV}`);
    });

  } catch (error) {
    console.error('❌ Failed to bootstrap application:', error.message);
    process.exit(1);
  }
}

bootstrap();
```

